// source of truth: edit it, not the review document. Typed data only: no code, no AI, no network.
//
// - The 17 first entries are the original skills; their ids and names never change (tests and saved reports use them).
// - `aliases` are exactly what will match (after the normalising in lib/engine/skillIds.ts).
// - `undecided` are aliases in doubt: they do NOT match until the owner decides.
// - `unsure` lists German names or aliases the owner still has to check (they match like any other).
// - `exactOnly`: a single letter or a very common word; it matches only when the whole name equals it.
// - `source`: existing, test ad (a name seen in ad-01 to ad-08), CV, or general (general knowledge, seen in no test material).

export type VocabEntry = {
  id: string;
  name: string;
  de: string;
  aliases: string[];
  undecided: string[];
  unsure: string[];
  source: string;
  flag: string;
  exactOnly?: true;
};

